#!/usr/bin/env python3
"""
Full signal IC diagnostic sweep — READ-ONLY.

Correct forward loading: forward snapshots are looked up globally (nearest snapshot
on/after base+horizon, within +7d tolerance). If none, that base date is UNOBSERVABLE
(excluded), never silently zero/NaN.

No model/ranker/selector/production changes. Pure measurement.
"""
import csv, math, statistics
from pathlib import Path
from datetime import datetime, timedelta

SNAP_ROOT = Path("/mnt/c/Projects/biotech_screener/biotech-screener/data/snapshots")
FIELDS = ["final_score", "catalyst_score", "catalyst_decay_w", "coinvest_score_z", "financial_score"]
HORIZONS = [5, 10, 20, 60]
KEEP = set(FIELDS) | {"ticker", "close_price", "actionable_rank", "eligible", "catalyst_in_window"}
FWD_TOL = 7  # days: accept nearest snapshot up to base+horizon+7

def sf(v):
    if v is None or v == "": return float("nan")
    try:
        f = float(v); return f if f == f else float("nan")
    except (ValueError, TypeError): return float("nan")

def load_all():
    snaps = {}
    for d in sorted(SNAP_ROOT.iterdir()):
        if not d.is_dir() or len(d.name) != 10: continue
        rf = d / "rankings.csv"
        if not rf.exists() or rf.stat().st_size < 1000: continue
        rows = {}
        with open(rf) as f:
            for r in csv.DictReader(f):
                t = r.get("ticker", "").strip()
                if t: rows[t] = {k: r.get(k, "") for k in KEEP}
        if rows: snaps[d.name] = rows
    return snaps

def rank_vals(vals):
    n = len(vals); idx = sorted(range(n), key=lambda i: vals[i]); rk = [0.0]*n; i = 0
    while i < n:
        j = i
        while j < n and vals[idx[j]] == vals[idx[i]]: j += 1
        a = (i + j - 1)/2.0 + 1.0
        for k in range(i, j): rk[idx[k]] = a
        i = j
    return rk

def spearman(x, y):
    pairs = [(a, b) for a, b in zip(x, y) if a == a and b == b]
    if len(pairs) < 5: return float("nan"), 0
    xs, ys = zip(*pairs); n = len(xs)
    rx, ry = rank_vals(list(xs)), rank_vals(list(ys))
    mx, my = sum(rx)/n, sum(ry)/n
    num = sum((rx[i]-mx)*(ry[i]-my) for i in range(n))
    dx = math.sqrt(sum((rx[i]-mx)**2 for i in range(n))); dy = math.sqrt(sum((ry[i]-my)**2 for i in range(n)))
    if dx < 1e-9 or dy < 1e-9: return 0.0, n
    return num/(dx*dy), n

def nearest_forward(all_dates, base, horizon):
    target = datetime.strptime(base, "%Y-%m-%d") + timedelta(days=horizon)
    cap = target + timedelta(days=FWD_TOL)
    for d in all_dates:
        dd = datetime.strptime(d, "%Y-%m-%d")
        if dd >= target and dd <= cap:
            return d
    return None

def seg_filter(row, segment):
    if segment == "cohort":
        r = sf(row.get("actionable_rank")); return r == r and r <= 60
    if segment == "all_eligible":
        return row.get("eligible", "").strip() == "1"
    if segment == "in_window":
        return row.get("catalyst_in_window", "").strip() == "1"
    return False

def measure(snaps, all_dates, base, field, horizon, segment):
    """One base-date IC. Returns (ic, n_names) or None if forward missing."""
    fwd = nearest_forward(all_dates, base, horizon)
    if fwd is None or fwd not in snaps: return None
    base_rows = snaps[base]; fwd_rows = snaps[fwd]
    scores, rets = [], []
    for t, row in base_rows.items():
        if not seg_filter(row, segment): continue
        s = sf(row.get(field))
        bp = sf(row.get("close_price"))
        fr = fwd_rows.get(t)
        if fr is None: continue
        fp = sf(fr.get("close_price"))
        if s != s or bp != bp or fp != fp or bp <= 0: continue
        scores.append(s); rets.append((fp - bp)/bp)
    if len(scores) < 5: return None
    ic, n = spearman(scores, rets)
    if ic != ic: return None
    return ic, n

def window_dates(all_dates, start, end):
    return [d for d in all_dates if start <= d <= end]

WINDOWS = [
    ("Feb2026", "2026-02-01", "2026-02-28"),
    ("Mar2026", "2026-03-01", "2026-03-31"),
    ("Apr2026", "2026-04-01", "2026-04-30"),
    ("May2026", "2026-05-01", "2026-05-31"),
    ("FebMay2026", "2026-02-01", "2026-05-31"),
]

def aggregate(snaps, all_dates, base_dates, field, horizon, segment):
    ics = []
    for b in base_dates:
        r = measure(snaps, all_dates, b, field, horizon, segment)
        if r is not None: ics.append(r[0])
    if len(ics) < 3:
        return {"n": len(ics), "status": "UNOBSERVABLE"}
    mean = statistics.mean(ics); std = statistics.stdev(ics) if len(ics) > 1 else 0.0
    t = mean/(std/math.sqrt(len(ics))) if std > 1e-12 else 0.0
    return {"n": len(ics), "mean_ic": mean, "std": std, "t": t,
            "pct_pos": sum(1 for x in ics if x > 0)/len(ics), "status": "OK"}

def main():
    snaps = load_all()
    all_dates = sorted(snaps.keys())
    print(f"Loaded {len(all_dates)} snapshots: {all_dates[0]} .. {all_dates[-1]}\n")

    out = []
    for seg in ["cohort", "all_eligible", "in_window"]:
        out.append(f"\n{'='*78}\nSEGMENT: {seg}\n{'='*78}")
        for wname, ws, we in WINDOWS:
            bdates = window_dates(all_dates, ws, we)
            out.append(f"\n--- {wname} ({len(bdates)} base snapshots) ---")
            out.append(f"{'field':<18} " + " ".join(f"{'T+'+str(h):>14}" for h in HORIZONS))
            for field in FIELDS:
                cells = []
                for h in HORIZONS:
                    a = aggregate(snaps, all_dates, bdates, field, h, seg)
                    if a["status"] == "UNOBSERVABLE":
                        cells.append(f"{'UNOBS(n='+str(a['n'])+')':>14}")
                    else:
                        flag = "*" if a["mean_ic"] >= 0.0200 else " "
                        cells.append(f"{a['mean_ic']:+.3f}/t{a['t']:+.1f}{flag}".rjust(14))
                out.append(f"{field:<18} " + " ".join(cells))
    text = "\n".join(out)
    print(text)
    Path("/tmp/claude-1000/-home-arrenchulz/f8cad054-3bef-408b-bf98-f7e058fe00a5/scratchpad/sweep_out.txt").write_text(text)

if __name__ == "__main__":
    main()

